// /jev-mod compact's selection: what Jev is asked, and what the conversation becomes after a
// compaction with no summariser.
//
// Two kinds of thing are judged. A message's text, in a message holding no tool call or result,
// is kept or dropped (`unitsOf`, `keepOnly`): it goes only when Jev confidently marked it drop.
// A tool call with its result is judged as a pair (`trimsOf`): Jev says whether it stays at all,
// and for a long result how much of its start and end stays; the full call and result are saved
// to a file first. A dropped pair loses its call and its result together, so every tool_use that
// stays keeps its tool_result; a message left with neither text nor a tool block goes, and one
// left with text stays (`rebuilt`). The text of a message that holds a tool call or result is not
// sent to Jev: a pair's fate decides that message.

import { KEEP_LAST, TRIM_SHOWN, type TrimView } from '../../engine/compact'
import { isSensitive } from '../../engine/privacy'

export type Msg = {
  role: string
  text: string
  toolUses?: readonly { tool_use_id: string; tool?: string; input?: Record<string, unknown>; text?: string; isError?: boolean }[]
  toolResults?: readonly { tool_use_id: string; text?: string; isError?: boolean; result?: unknown }[]
  handle?: string
}

/** The last messages, kept whatever Jev says: the same tail the engine keeps by default. */
export const ALWAYS_KEEP_LAST = KEEP_LAST

/** A result this short or shorter is asked keep or drop only: trimming it would save too little. */
export const TRIM_MIN_CHARS = 1300

/** One text Jev judges keep or drop, by message index. */
export type Unit = { text: number }

// The arguments that say what a call did, in the order they are shown.
const MAIN_ARGS = ['command', 'file_path', 'notebook_path', 'path', 'pattern', 'glob', 'url', 'query', 'skill', 'description', 'prompt']

/** A call's main argument (its command, path, pattern...), else its whole input as JSON. */
export function argsOf(input: Record<string, unknown> | undefined): string {
  if (!input) return ''
  const main = MAIN_ARGS.map(k => input[k]).filter((v): v is string => typeof v === 'string' && v.trim() !== '')
  if (main.length) return main.join(' ')
  try { return JSON.stringify(input) } catch { return '' }
}

const hasTools = (m: Msg) => !!(m.toolUses?.length || m.toolResults?.length)

/**
 * What to send Jev for keep or drop, in order, with the message each entry judges: the text of
 * each message outside the last ALWAYS_KEEP_LAST that holds no tool call or result.
 */
export function unitsOf(messages: readonly Msg[]): { units: Unit[]; toJev: { role: string; content: string }[] } {
  const tail = Math.max(0, messages.length - ALWAYS_KEEP_LAST)
  const units: Unit[] = []
  const toJev: { role: string; content: string }[] = []
  messages.forEach((m, i) => {
    if (i >= tail || hasTools(m) || typeof m.text !== 'string' || !m.text.trim()) return
    units.push({ text: i })
    toJev.push({ role: m.role, content: m.text })
  })
  return { units, toJev }
}

/**
 * An assistant message with no text and no tool call: its thinking alone, which the transcript
 * keeps as a message of its own. `rebuilt` hands every assistant message back built, which leaves
 * thinking out, so this one is left empty and goes (see there).
 */
export const isThinkingOnly = (m: Msg) => m.role === 'assistant' && !hasTools(m) && !(typeof m.text === 'string' && m.text.trim())

/**
 * The messages `/jev-mod compact` keeps, in order. `fates` is indexed by position in `units`
 * (the engine already turns a low-confidence drop into keep). A message goes only when its text
 * is a unit marked drop and it holds no tool call or result; the last ALWAYS_KEEP_LAST stay.
 */
export function keepOnly<M extends Msg>(messages: readonly M[], units: readonly Unit[], fates: Record<string, string>): M[] {
  const tail = Math.max(0, messages.length - ALWAYS_KEEP_LAST)
  const drop = new Set<number>()
  units.forEach((u, j) => {
    if (fates[String(j)] === 'drop' && u.text < tail && messages[u.text] && !hasTools(messages[u.text]!)) drop.add(u.text)
  })
  return messages.filter((_, i) => !drop.has(i))
}

/** One tool call with its result, both in the conversation. */
export type Pair = { id: string; tool: string; input: Record<string, unknown>; text: string; isError: boolean; call: number; result: number }

function pairsOf(messages: readonly Msg[]): Pair[] {
  const calls = new Map<string, { i: number; tool: string; input: Record<string, unknown> }>()
  messages.forEach((m, i) => {
    for (const use of m.toolUses ?? []) calls.set(use.tool_use_id, { i, tool: use.tool || 'tool', input: use.input ?? {} })
  })
  const pairs: Pair[] = []
  messages.forEach((m, i) => {
    for (const r of m.toolResults ?? []) {
      const call = calls.get(r.tool_use_id)
      if (!call || typeof r.text !== 'string') continue // a result without its call is left whole
      pairs.push({ id: r.tool_use_id, tool: call.tool, input: call.input, text: r.text, isError: !!r.isError, call: call.i, result: i })
    }
  })
  return pairs
}

/**
 * The tool pairs Jev is asked about, each with what it sees: the call, the result's size, and its
 * first and last TRIM_SHOWN characters (the engine redacts them), or all of it when it is
 * TRIM_MIN_CHARS or shorter (keep or drop only). A pair with a half among the last ALWAYS_KEEP_LAST
 * messages may be trimmed but never dropped, so it is sent only when its result is long. Left
 * whole and not sent: a short pair in that tail, and a pair whose call or full result looks
 * sensitive.
 */
export function trimsOf(messages: readonly Msg[]): { pairs: Pair[]; views: TrimView[] } {
  const tail = Math.max(0, messages.length - ALWAYS_KEEP_LAST)
  const pairs: Pair[] = []
  const views: TrimView[] = []
  for (const p of pairsOf(messages)) {
    const inTail = p.call >= tail || p.result >= tail
    const points = [...p.text]
    const long = points.length > TRIM_MIN_CHARS
    if (inTail && !long) continue
    const arg = argsOf(p.input)
    if (isSensitive(`${p.tool} ${arg}\n${p.text}`)) continue
    pairs.push(p)
    views.push({ tool: p.tool, arg, size: points.length, isError: p.isError, trim: long, ...(inTail ? { mayDrop: false } : {}),
      head: long ? points.slice(0, TRIM_SHOWN).join('') : p.text, tail: long ? points.slice(-TRIM_SHOWN).join('') : '' })
  }
  return { pairs, views }
}

const count = (n: number) => n.toLocaleString('en-US')

/** The line that stands where a result's middle was: what was cut, and the file that holds it all. */
export function placeholder(p: Pair, head: number, tail: number, file: string): string {
  const size = [...p.text].length
  const arg = argsOf(p.input).replace(/\s+/g, ' ').trim()
  const shown = arg.length > 160 ? `${arg.slice(0, 157)}...` : arg
  const kept = head && tail ? `its first ${head} and last ${tail}` : head ? `its first ${head}` : tail ? `its last ${tail}` : 'none of it'
  return `[jev-mod compact trimmed this ${p.tool}${shown ? ` (${shown})` : ''} result: ${count(size - head - tail)} of its ` +
    `${count(size)} characters were cut, keeping ${kept}. The full call and result are in ${file}; Read it if you need the rest.]`
}

/** The result with its middle replaced by `note`, or null when that would not make it shorter. */
export function cut(text: string, head: number, tail: number, note: string): string | null {
  const points = [...text]
  if (head + tail >= points.length) return null
  const out = [head ? points.slice(0, head).join('') : null, note, tail ? points.slice(-tail).join('') : null]
    .filter((s): s is string => s !== null).join('\n')
  return [...out].length < points.length ? out : null
}

/** What a saved file holds: the call and its full result, so a later step can read what was cut. */
export function saved(p: Pair, session: string | null): string {
  let input: string
  try { input = JSON.stringify(p.input, null, 2) } catch { input = String(p.input) }
  return [`jev-mod compact saved this tool call and its full result before trimming the result in the conversation` +
    `${session ? ` (session ${session})` : ''}.`, `tool: ${p.tool}`, `tool_use_id: ${p.id}`, `input:\n${input}`,
    `result${p.isError ? ' (error)' : ''}, ${count([...p.text].length)} characters:`, p.text].join('\n')
}

/**
 * The messages with each trimmed result's text replaced (`texts`, by tool_use_id) and each
 * dropped pair's call and result taken out (`drop`, by tool_use_id). Every assistant message and
 * every message that holds a tool result is handed back without the engine's `handle`, so the
 * engine builds it from its role, text and tool blocks; a message left with no text and no tool
 * block goes. Only user messages with no tool result stay the engine's own. Why, from bench runs
 * (`claude -p --resume` after the compaction):
 *
 * - A result message kept with its handle is written after the compact boundary with its old
 *   parent, the call's original row before the boundary, so a resumed session walks back through
 *   everything the compaction removed (169k tokens read where the compaction reported 28k).
 * - An assistant message kept with its handle keeps its API message id, and a resumed session
 *   gathers every row of the file with that id into one message: the thinking, the dropped tool
 *   calls (and then their results) and the very text again come back from before the boundary
 *   (82k read on that session; 26k once every assistant message was built, with its own id).
 *
 * A built message carries no thinking, so thinking goes from every assistant turn, the tail's
 * too. The API allows it: a previous turn's thinking may be left out, and only the last assistant
 * turn of an unfinished tool loop must keep it, which a compaction between turns never has. A
 * trimmed result loses its stored record (`result`), which held the bulk.
 */
export function rebuilt<M extends Msg>(messages: readonly M[], texts: ReadonlyMap<string, string>, drop: ReadonlySet<string> = new Set()): M[] {
  const out: M[] = []
  for (const m of messages) {
    const touched = m.role === 'assistant' || !!m.toolResults?.length || m.toolUses?.some(u => drop.has(u.tool_use_id))
    if (!touched) { out.push(m); continue }
    const { handle: _handle, ...rest } = m
    const toolUses = (m.toolUses ?? []).filter(u => !drop.has(u.tool_use_id))
    const toolResults = (m.toolResults ?? []).filter(r => !drop.has(r.tool_use_id)).map(r => {
      const text = texts.get(r.tool_use_id)
      if (text === undefined) return r
      const { result: _result, ...kept } = r
      return { ...kept, text }
    })
    if (!toolUses.length && !toolResults.length && !(typeof m.text === 'string' && m.text.trim())) continue
    out.push({ ...rest, ...(m.toolUses ? { toolUses } : {}), ...(m.toolResults ? { toolResults } : {}) } as unknown as M)
  }
  return out
}

files.src/engine/lanes.ts:
// Lanes: the smallest model and lowest effort that should still get a piece of work right.
//
// Ported from jev-skills' jevkit/lanes.py (classify, targets), the decide.decide that runs its
// policy, and limits.py's budget arithmetic. Four lanes, small < medium < high < escalate, each
// a model and effort for the host; the decision model reads the work, the lane policy's rules
// (code) turn its readings into the lane. `step` and `evidence` are for loops that delegate
// work and check it; the mod routes turns and has no use for them.

import { ask, costOf, JevError, USD_PER_INPUT_TOKEN, type Host } from './client'
import { apply, DEFAULT_BAND, drifted, preDecide, readings, untuned, type Facts, type Policy } from './policy'
import { isSensitive, redact } from './privacy'
import { encode } from './pyjson'
import { pyRound } from './pyre'

export const LANES = ['small', 'medium', 'high', 'escalate'] as const
export type Target = Record<string, string>

// The Claude Code subagents jev-skills' installer writes (jev-lane-*.md) carry the same model
// and effort in their frontmatter, so a lane is also the agent to delegate it to.
export const CLAUDE_CODE_TARGETS: Record<string, Target> = {
  small: { agent: 'jev-lane-small', model: 'haiku', effort: 'low' },
  medium: { agent: 'jev-lane-medium', model: 'sonnet', effort: 'medium' },
  high: { agent: 'jev-lane-high', model: 'opus', effort: 'medium' },
  escalate: { agent: 'jev-lane-escalate', model: 'opus', effort: 'high' },
}

const isObject = (v: unknown): v is Record<string, unknown> => !!v && typeof v === 'object' && !Array.isArray(v)
/** The fields a policy reads: `state_fields`, or every field when it names none (Python's `wanted or state`). */
const fieldsOf = (policy: Policy, state: Record<string, unknown>) => (policy.state_fields?.length ? policy.state_fields : Object.keys(state))

/**
 * Claude Code's lane -> model/effort table with each lanes.json laid on top, least specific
 * first (`{"claude-code": {"small": {"model": "sonnet"}}}`): a lane or field a file does not
 * name keeps the default, and only text and numbers are taken, as text.
 */
export function targets(tables: unknown[]): Record<string, Target> {
  const out: Record<string, Target> = Object.fromEntries(Object.entries(CLAUDE_CODE_TARGETS).map(([lane, spec]) => [lane, { ...spec }]))
  for (const table of tables) {
    if (!isObject(table) || !isObject(table['claude-code'])) continue
    for (const [lane, spec] of Object.entries(table['claude-code'])) {
      if (!(lane in out) || !isObject(spec)) continue
      for (const [key, value] of Object.entries(spec)) {
        // isinstance(v, (str, int, float)): a bool is an int to Python, so it is taken too, as "True"
        if (typeof value === 'string') out[lane]![key] = value
        else if (typeof value === 'number') out[lane]![key] = String(value)
        else if (typeof value === 'boolean') out[lane]![key] = value ? 'True' : 'False'
      }
    }
  }
  return out
}

// ── the daily budget (limits.py) ─────────────────────────────────────────────

/** Where the decision engine asks before a request and reports after one; the caller keeps the counter. */
export interface Limits {
  admit(shadow: boolean): Promise<[boolean, string]>
  charge(usd: number): Promise<void>
}

export const LIMIT_DEFAULTS = { rpm: 1000, daily_usd: 1.0, shadow_share: 0.8 }
export type LimitConfig = typeof LIMIT_DEFAULTS
export type LimitState = { minute?: number; count?: number; day?: string; usd?: number }

/** limits.json's values over the defaults; a value that is not a number of zero or more is ignored. */
export function limitConfig(raw: unknown): LimitConfig {
  const out = { ...LIMIT_DEFAULTS }
  if (!isObject(raw)) return out
  for (const key of Object.keys(LIMIT_DEFAULTS) as (keyof LimitConfig)[]) {
    const value = raw[key]
    if (typeof value === 'number' && value >= 0) out[key] = value
  }
  return out
}

/** The counter moved to this minute and this (local) day. */
export function roll(state: LimitState, nowMs: number): LimitState {
  const out = { ...state }
  const minute = Math.floor(nowMs / 60_000)
  if (out.minute !== minute) Object.assign(out, { minute, count: 0 })
  const d = new Date(nowMs)
  const day = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
  if (out.day !== day) Object.assign(out, { day, usd: 0.0 })
  return out
}

/** limits.admit: whether one more request may go, and the counter after it. Shadow work stops first. */
export function admitState(state: LimitState, config: LimitConfig, nowMs: number, shadow: boolean): [boolean, string, LimitState] {
  const now = roll(state, nowMs)
  if (Number(now.usd ?? 0) >= config.daily_usd) return [false, 'skipped_budget', now]
  const ceiling = config.rpm * (shadow ? config.shadow_share : 1.0)
  if (Number(now.count ?? 0) >= ceiling) return [false, 'skipped_rate', now]
  return [true, 'ok', { ...now, count: Number(now.count ?? 0) + 1 }]
}

/** limits.charge: the day's spend after one request. */
export function chargeState(state: LimitState, nowMs: number, usd: number): LimitState {
  const now = roll(state, nowMs)
  return { ...now, usd: pyRound(Number(now.usd ?? 0) + usd, 8) }
}

// ── one policy decision (decide.py) ──────────────────────────────────────────

const DEFAULT_FIELD_CHARS = 1500
const MAX_DEPTH = 4

function redactValue(value: unknown, limit: number, depth = 0): unknown {
  if (typeof value === 'string') return redact(value, limit)
  if (value === null || value === undefined || typeof value === 'boolean' || typeof value === 'number') return value ?? null
  if (depth >= MAX_DEPTH) return redact(encode(value, { ensureAscii: true }), limit)
  if (Array.isArray(value)) return value.slice(0, 64).map(v => redactValue(v, limit, depth + 1))
  if (isObject(value)) return Object.fromEntries(Object.entries(value).slice(0, 64).map(([k, v]) => [k, redactValue(v, limit, depth + 1)]))
  return redact(String(value), limit)
}

/** Only the fields the policy names, each redacted and capped: a long state makes the model worse. */
export function prepareState(state: unknown, policy: Policy): unknown {
  const limits = policy.field_limits ?? {}
  if (isObject(state)) {
    return Object.fromEntries(fieldsOf(policy, state).filter(key => key in state).map(key => [key, redactValue(state[key], Number(limits[key] ?? DEFAULT_FIELD_CHARS))]))
  }
  return redactValue(state, Number(limits._ ?? 4000))
}

export type Decision = {
  action: string; rule_action: string | null; matched_rule: number | null; matched_pre_rule?: number
  fired_rules: number[]; annotations: string[]; unsure: string[]; answers: Record<string, unknown>
  jev_model: string | null; drift: boolean | null; untuned?: boolean; latency_ms: number | null; input_tokens: number | null
  cost_usd: number; list_usd: number; feature: string; mode: string; error: string | null; status: string
  fallback_used: boolean; sent_to_jev: boolean; source: 'code' | 'jev' | 'fallback'; provider?: string
}

export type DecideOptions = { mode?: 'live' | 'shadow'; facts?: Facts; timeoutMs?: number; retries?: number; limits?: Limits }

/** Run one policy against one state. Never throws for anything the model or the network does. */
export async function decide(host: Host, state: unknown, policy: Policy, opts: DecideOptions = {}): Promise<Decision> {
  const mode = opts.mode ?? 'live'
  const shadow = mode === 'shadow'
  const feature = String(policy.feature || policy.name)
  const blank = { rule_action: null, matched_rule: null, fired_rules: [], annotations: [], unsure: [], answers: {},
    jev_model: null, drift: null, cost_usd: 0.0, list_usd: 0.0, feature, mode }
  const fallback = (error: string, status = 'error', sent = false): Decision => ({ ...blank, action: policy.on_error,
    latency_ms: null, input_tokens: null, error, status, fallback_used: true, sent_to_jev: sent, source: 'fallback' })

  const pre = preDecide(policy, opts.facts)
  if (pre) {
    return { ...blank, action: pre.action, rule_action: pre.action, matched_pre_rule: pre.matched_pre_rule, latency_ms: 0,
      input_tokens: 0, error: null, status: 'code', fallback_used: false, sent_to_jev: false, source: 'code' }
  }
  // decide.py probed json.dumps of the fields, which escapes every non-ASCII character
  // ("\u0664"): a card in Arabic-Indic digits or a key behind an accented letter, which
  // privacy.ts catches in the text, passed escaped. The port probes the text as it is.
  const probe = typeof state === 'string' ? state : encode(isObject(state)
    ? Object.fromEntries(fieldsOf(policy, state).filter(k => k in state).map(k => [k, state[k]])) : state, { ensureAscii: false })
  // Never sent: the caller gets exactly what it would have done without the model.
  if (isSensitive(probe)) return fallback('sensitive_not_sent', 'skipped')
  const prepared = prepareState(state, policy)
  if (opts.limits) {
    const [allowed, reason] = await opts.limits.admit(shadow)
    if (!allowed) return fallback(reason, 'skipped')
  }
  let reply
  try {
    reply = await ask(host, prepared, policy.questions, { timeoutMs: opts.timeoutMs ?? 4000, retries: opts.retries ?? 1 })
  } catch (error) {
    if (!(error instanceof JevError)) throw error // a question the client refused: a policy bug
    return fallback(error.code, 'error', !['no_key', 'state_too_large', 'over_input_limit', 'invalid_endpoint'].includes(error.code))
  }
  const values = readings(policy.questions, reply.answers, policy.uncertain_band ?? DEFAULT_BAND)
  const applied = apply(policy, values, opts.facts)
  const drift = drifted(policy.tuned_on, reply.jev_model)
  const fallbackUsed = !!drift && !shadow
  const action = fallbackUsed ? (policy.on_drift || policy.on_error) : applied.action
  const listUsd = pyRound(Number(reply.input_tokens ?? 0) * USD_PER_INPUT_TOKEN, 8)
  const costUsd = costOf(reply)
  if (opts.limits) await opts.limits.charge(costUsd)
  return {
    action, rule_action: applied.action, matched_rule: applied.matched_rule, fired_rules: applied.fired_rules,
    annotations: applied.annotations, unsure: applied.unsure, answers: values, jev_model: reply.jev_model, drift,
    untuned: untuned(policy, reply.provider), latency_ms: reply.latency_ms, input_tokens: reply.input_tokens,
    cost_usd: costUsd, list_usd: listUsd, feature, mode, error: fallbackUsed ? 'drift' : null, status: 'ok',
    fallback_used: fallbackUsed, sent_to_jev: true, provider: reply.provider, source: fallbackUsed ? 'fallback' : 'jev',
  }
}

// ── classify ─────────────────────────────────────────────────────────────────

export type Classified = { lane: string; target: Target | null; host: 'claude-code'; decision: Decision; why?: string }

export type ClassifyOptions = DecideOptions & { context?: string; tables?: unknown[] }

/** The first lane for a piece of work: one request, three questions, the policy's rules on the answers. */
export async function classify(host: Host, task: string, policy: Policy, opts: ClassifyOptions = {}): Promise<Classified> {
  const state = { task, ...(opts.context ? { context: opts.context } : {}) }
  const decision = await decide(host, state, policy, opts)
  const lane = decision.action
  const out: Classified = { lane, target: targets(opts.tables ?? [])[lane] ?? null, host: 'claude-code', decision }
  if (lane === 'keep_current') {
    out.target = null
    out.why = decision.fallback_used ? 'Jev could not judge; keep the model you were going to use'
      : decision.source === 'code' ? 'keep the model already chosen'
      : 'Jev read this as work a person should look at first; keep the current model'
  }
  return out
}

